class Solution {
    public boolean isConsecutive(int[] nums) {
        int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
        Set<Integer> seen = new HashSet<>();
        for (int x : nums) {
            if (!seen.add(x)) return false;
            min = Math.min(min, x);
            max = Math.max(max, x);
        }
        return max - min == nums.length - 1;
    }
}
